class FifoOrderer<T> {
  private next = 0;
  private pending = new Map<number,T>();
  private out: T[] = [];
  ingest(seq: number, rec: T) {
    this.pending.set(seq, rec);
    while (this.pending.has(this.next)) {
      this.out.push(this.pending.get(this.next)!);
      this.pending.delete(this.next);
      this.next++;
    }
  }
  flush() { return this.out.splice(0); }
}
